import heapq

def solve(data):
    nodes = data.get("nodes", [])
    edges = data.get("edges", [])

    adj = {}
    indeg = {}
    for n in nodes:
        adj[n] = []
        indeg[n] = 0

    seen = set()
    for edge in edges:
        s, d = edge[0], edge[1]
        if (s, d) in seen:
            continue
        seen.add((s, d))
        adj[s].append(d)
        indeg[d] += 1

    heap = [n for n in nodes if indeg[n] == 0]
    heapq.heapify(heap)

    order = []
    while heap:
        n = heapq.heappop(heap)
        order.append(n)
        for m in adj[n]:
            indeg[m] -= 1
            if indeg[m] == 0:
                heapq.heappush(heap, m)

    if len(order) != len(indeg):
        return None
    return order
