from collections import deque


def solve(data):
    src = data
    if isinstance(data, dict) and isinstance(data.get("input"), dict):
        src = data["input"]
    if not isinstance(src, dict):
        return []

    values = src.get("values")
    if values is None:
        values = []
    values = list(values)
    width = src.get("width", 0)

    n = len(values)
    if width <= 0 or width > n:
        return []

    dq = deque()  # indices of candidates, values strictly decreasing
    result = []
    for i in range(n):
        v = values[i]
        while dq and values[dq[-1]] <= v:
            dq.pop()
        dq.append(i)
        if dq[0] <= i - width:
            dq.popleft()
        if i >= width - 1:
            result.append(values[dq[0]])
    return result
